    public async Task<IReadOnlyList<LeaveTypeItem>> GetTypesAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT id,code,name,is_paid,requires_attachment,allow_half_day,max_consecutive_days,is_active FROM leave_mgmt.leave_type ORDER BY is_active DESC,lower(name)",c);await using var r=await q.ExecuteReaderAsync();var a=new List<LeaveTypeItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetBoolean(3),r.GetBoolean(4),r.GetBoolean(5),D(r,6),r.GetBoolean(7)));return a;}
    public async Task<IReadOnlyList<LeavePolicyItem>> GetPoliciesAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT p.id,p.leave_type_id,t.name,p.name,p.annual_entitlement,p.accrual_frequency,p.carry_forward_limit,p.allow_negative_balance,p.effective_from,p.effective_to FROM leave_mgmt.leave_policy p JOIN leave_mgmt.leave_type t ON t.id=p.leave_type_id ORDER BY p.effective_from DESC,lower(p.name)",c);await using var r=await q.ExecuteReaderAsync();var a=new List<LeavePolicyItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetDecimal(4),r.GetString(5),r.GetDecimal(6),r.GetBoolean(7),r.GetFieldValue<DateOnly>(8),ND(r,9)));return a;}
    public async Task<IReadOnlyList<EmployeeLeavePolicyItem>> GetAssignmentsAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT x.id,x.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,x.policy_id,p.name,t.name,x.effective_from,x.effective_to,(p.effective_from<=current_date AND (p.effective_to IS NULL OR p.effective_to>current_date) AND t.is_active) FROM leave_mgmt.employee_leave_policy x JOIN hr.employee e ON e.id=x.employee_id JOIN leave_mgmt.leave_policy p ON p.id=x.policy_id JOIN leave_mgmt.leave_type t ON t.id=p.leave_type_id ORDER BY x.effective_from DESC,lower(e.first_name)",c);await using var r=await q.ExecuteReaderAsync();var a=new List<EmployeeLeavePolicyItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetGuid(4),r.GetString(5),r.GetString(6),r.GetFieldValue<DateOnly>(7),ND(r,8),r.GetBoolean(9)));return a;}
    public async Task<IReadOnlyList<LeaveBalanceItem>> GetBalancesAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT b.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,b.leave_type_id,t.name,b.balance,EXISTS(SELECT 1 FROM leave_mgmt.employee_leave_policy ep JOIN leave_mgmt.leave_policy p ON p.id=ep.policy_id WHERE ep.employee_id=b.employee_id AND p.leave_type_id=b.leave_type_id AND ep.effective_from<=current_date AND (ep.effective_to IS NULL OR ep.effective_to>current_date) AND p.effective_from<=current_date AND (p.effective_to IS NULL OR p.effective_to>current_date) AND t.is_active) FROM reporting.v_leave_balance b JOIN hr.employee e ON e.id=b.employee_id JOIN leave_mgmt.leave_type t ON t.id=b.leave_type_id ORDER BY lower(e.first_name),lower(t.name)",c);await using var r=await q.ExecuteReaderAsync();var a=new List<LeaveBalanceItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetGuid(3),r.GetString(4),r.GetDecimal(5),r.GetBoolean(6)));return a;}
    public async Task<IReadOnlyList<LeaveRequestItem>> GetRequestsAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT x.id,x.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,b.name,x.leave_type_id,t.name,x.start_date,x.end_date,x.requested_days,x.reason,x.status,x.decision_notes,x.requested_at,EXISTS(SELECT 1 FROM leave_mgmt.employee_leave_policy ep JOIN leave_mgmt.leave_policy p ON p.id=ep.policy_id WHERE ep.employee_id=x.employee_id AND p.leave_type_id=x.leave_type_id AND ep.effective_from<=current_date AND (ep.effective_to IS NULL OR ep.effective_to>current_date) AND p.effective_from<=current_date AND (p.effective_to IS NULL OR p.effective_to>current_date) AND t.is_active),x.attachment_object_key FROM leave_mgmt.leave_request x JOIN hr.employee e ON e.id=x.employee_id JOIN core.branch b ON b.id=x.branch_id JOIN leave_mgmt.leave_type t ON t.id=x.leave_type_id ORDER BY CASE x.status WHEN 'pending' THEN 0 ELSE 1 END,x.created_at DESC",c);await using var r=await q.ExecuteReaderAsync();var a=new List<LeaveRequestItem>();while(await r.ReadAsync())a.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetGuid(5),r.GetString(6),r.GetFieldValue<DateOnly>(7),r.GetFieldValue<DateOnly>(8),r.GetDecimal(9),S(r,10),r.GetString(11),S(r,12),DTO(r,13),r.GetBoolean(14),S(r,15)));return a;}
    public async Task<IReadOnlyList<LeaveLedgerItem>> GetLedgerAsync(){await using var c=await Open();await using var q=new NpgsqlCommand("SELECT l.id,l.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,t.name,l.transaction_date,l.quantity,l.entry_type,l.reference FROM leave_mgmt.leave_ledger l JOIN hr.employee e ON e.id=l.employee_id JOIN leave_mgmt.leave_type t ON t.id=l.leave_type_id ORDER BY l.transaction_date DESC,l.id DESC",c);await using var r=await q.ExecuteReaderAsync();var a=new List<LeaveLedgerItem>();while(await r.ReadAsync())a.Add(new(r.GetInt64(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetFieldValue<DateOnly>(5),r.GetDecimal(6),r.GetString(7),S(r,8)));return a;}

    public async Task SaveTypeAsync(LeaveTypeForm m,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO leave_mgmt.leave_type(code,name,is_paid,requires_attachment,allow_half_day,max_consecutive_days,is_active,created_by,updated_by) VALUES(@code,@name,@paid,@attachment,@half,@max,@active,@actor,@actor)":"UPDATE leave_mgmt.leave_type SET code=@code,name=@name,is_paid=@paid,requires_attachment=@attachment,allow_half_day=@half,max_consecutive_days=@max,is_active=@active,updated_by=@actor WHERE id=@id",c);q.Parameters.AddWithValue("code",m.Id is null?BusinessCode.New("LVT"):m.Code);q.Parameters.AddWithValue("name",m.Name.Trim());q.Parameters.AddWithValue("paid",m.IsPaid);q.Parameters.AddWithValue("attachment",m.RequiresAttachment);q.Parameters.AddWithValue("half",m.AllowHalfDay);P(q,"max",m.MaxConsecutiveDays);q.Parameters.AddWithValue("active",m.IsActive);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id);await q.ExecuteNonQueryAsync();}
    public async Task SavePolicyAsync(LeavePolicyForm m,Guid actor){if(m.EffectiveTo<m.EffectiveFrom)throw new InvalidOperationException("Effective-to date cannot be before effective-from date.");await using var c=await Open();await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO leave_mgmt.leave_policy(leave_type_id,name,annual_entitlement,accrual_frequency,carry_forward_limit,allow_negative_balance,effective_from,effective_to,created_by,updated_by) VALUES(@type,@name,@annual,@frequency,@carry,@negative,@from,@to,@actor,@actor)":"UPDATE leave_mgmt.leave_policy SET leave_type_id=@type,name=@name,annual_entitlement=@annual,accrual_frequency=@frequency,carry_forward_limit=@carry,allow_negative_balance=@negative,effective_from=@from,effective_to=@to,updated_by=@actor WHERE id=@id",c);q.Parameters.AddWithValue("type",m.LeaveTypeId!.Value);q.Parameters.AddWithValue("name",m.Name.Trim());q.Parameters.AddWithValue("annual",m.AnnualEntitlement);q.Parameters.AddWithValue("frequency",m.AccrualFrequency);q.Parameters.AddWithValue("carry",m.CarryForwardLimit);q.Parameters.AddWithValue("negative",m.AllowNegativeBalance);q.Parameters.AddWithValue("from",m.EffectiveFrom);P(q,"to",m.EffectiveTo);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id);await q.ExecuteNonQueryAsync();}
    public async Task SaveAssignmentAsync(EmployeeLeavePolicyForm m,Guid actor){if(m.EffectiveTo<m.EffectiveFrom)throw new InvalidOperationException("Effective-to date cannot be before effective-from date.");await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO leave_mgmt.employee_leave_policy(employee_id,policy_id,effective_from,effective_to,created_by,updated_by) VALUES(@employee,@policy,@from,@to,@actor,@actor)":"UPDATE leave_mgmt.employee_leave_policy SET employee_id=@employee,policy_id=@policy,effective_from=@from,effective_to=@to,updated_by=@actor WHERE id=@id",c,tx);q.Parameters.AddWithValue("employee",m.EmployeeId!.Value);q.Parameters.AddWithValue("policy",m.PolicyId!.Value);q.Parameters.AddWithValue("from",m.EffectiveFrom);P(q,"to",m.EffectiveTo);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id);await q.ExecuteNonQueryAsync();if(m.Id is null&&m.AddOpeningBalance){await using var ledger=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_ledger(employee_id,leave_type_id,transaction_date,quantity,entry_type,reference,created_by,updated_by) SELECT @employee,leave_type_id,@date,annual_entitlement,'opening','Policy opening balance',@actor,@actor FROM leave_mgmt.leave_policy WHERE id=@policy AND annual_entitlement<>0",c,tx);ledger.Parameters.AddWithValue("employee",m.EmployeeId.Value);ledger.Parameters.AddWithValue("policy",m.PolicyId.Value);ledger.Parameters.AddWithValue("date",m.EffectiveFrom);ledger.Parameters.AddWithValue("actor",actor);await ledger.ExecuteNonQueryAsync();}await tx.CommitAsync();}
    public async Task AddBalanceAsync(LeaveBalanceForm m,Guid actor){if(m.Quantity==0)throw new InvalidOperationException("Quantity cannot be zero.");await using var c=await Open();await using var q=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_ledger(employee_id,leave_type_id,transaction_date,quantity,entry_type,reference,created_by,updated_by) VALUES(@employee,@type,current_date,@quantity,'adjustment',@reference,@actor,@actor)",c);q.Parameters.AddWithValue("employee",m.EmployeeId!.Value);q.Parameters.AddWithValue("type",m.LeaveTypeId!.Value);q.Parameters.AddWithValue("quantity",m.Quantity);q.Parameters.AddWithValue("reference",m.Reference.Trim());q.Parameters.AddWithValue("actor",actor);await q.ExecuteNonQueryAsync();}
    public async Task SetTypeActiveAsync(Guid id,bool active,Guid actor){await using var c=await Open();await using var q=new NpgsqlCommand("UPDATE leave_mgmt.leave_type SET is_active=@active,updated_by=@actor WHERE id=@id",c);q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("active",active);q.Parameters.AddWithValue("actor",actor);await q.ExecuteNonQueryAsync();}
