    public async Task SaveRequestAsync(LeaveRequestForm m,Guid actor){if(m.EndDate<m.StartDate)throw new InvalidOperationException("End date cannot be before start date.");await using var c=await Open();await using var tx=await c.BeginTransactionAsync();await using var type=new NpgsqlCommand("SELECT allow_half_day,max_consecutive_days FROM leave_mgmt.leave_type WHERE id=@id AND is_active=true",c,tx);type.Parameters.AddWithValue("id",m.LeaveTypeId!.Value);bool allowHalf;decimal? max;await using(var r=await type.ExecuteReaderAsync()){if(!await r.ReadAsync())throw new InvalidOperationException("Leave type is inactive.");allowHalf=r.GetBoolean(0);max=D(r,1);}await using(var access=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM leave_mgmt.employee_leave_policy ep JOIN leave_mgmt.leave_policy p ON p.id=ep.policy_id WHERE ep.employee_id=@employee AND p.leave_type_id=@type AND ep.effective_from<=@from AND (ep.effective_to IS NULL OR ep.effective_to>=@to) AND p.effective_from<=@from AND (p.effective_to IS NULL OR p.effective_to>=@to) AND (p.effective_to IS NULL OR p.effective_to>current_date))",c,tx)){access.Parameters.AddWithValue("employee",m.EmployeeId!.Value);access.Parameters.AddWithValue("type",m.LeaveTypeId.Value);access.Parameters.AddWithValue("from",m.StartDate);access.Parameters.AddWithValue("to",m.EndDate);if(!(bool)(await access.ExecuteScalarAsync())!)throw new InvalidOperationException("This employee has no active policy for the selected leave type.");}var days=m.IsHalfDay?0.5m:(decimal)(m.EndDate.DayNumber-m.StartDate.DayNumber+1);if(m.IsHalfDay&&!allowHalf)throw new InvalidOperationException("This leave type does not allow half-day requests.");if(m.IsHalfDay&&m.StartDate!=m.EndDate)throw new InvalidOperationException("Half-day request must use the same start and end date.");if(max is not null&&days>max)throw new InvalidOperationException($"Maximum consecutive leave is {max:0.##} days.");await using var branch=new NpgsqlCommand("SELECT branch_id FROM hr.employee_assignment WHERE employee_id=@employee AND effective_from<=@date AND(effective_to IS NULL OR effective_to>=@date) ORDER BY effective_from DESC LIMIT 1",c,tx);branch.Parameters.AddWithValue("employee",m.EmployeeId!.Value);branch.Parameters.AddWithValue("date",m.StartDate);var branchId=await branch.ExecuteScalarAsync() as Guid? ?? throw new InvalidOperationException("Employee has no active assignment.");await using var q=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_request(employee_id,branch_id,leave_type_id,start_date,end_date,requested_days,reason,status,requested_at,created_by,updated_by) VALUES(@employee,@branch,@type,@from,@to,@days,@reason,'pending',now(),@actor,@actor) RETURNING id",c,tx);q.Parameters.AddWithValue("employee",m.EmployeeId.Value);q.Parameters.AddWithValue("branch",branchId);q.Parameters.AddWithValue("type",m.LeaveTypeId.Value);q.Parameters.AddWithValue("from",m.StartDate);q.Parameters.AddWithValue("to",m.EndDate);q.Parameters.AddWithValue("days",days);q.Parameters.AddWithValue("reason",m.Reason.Trim());q.Parameters.AddWithValue("actor",actor);var id=(Guid)(await q.ExecuteScalarAsync())!;for(var date=m.StartDate;date<=m.EndDate;date=date.AddDays(1)){await using var d=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_request_day(leave_request_id,leave_date,day_fraction,created_by,updated_by) VALUES(@id,@date,@fraction,@actor,@actor)",c,tx);d.Parameters.AddWithValue("id",id);d.Parameters.AddWithValue("date",date);d.Parameters.AddWithValue("fraction",m.IsHalfDay?0.5m:1m);d.Parameters.AddWithValue("actor",actor);await d.ExecuteNonQueryAsync();}await tx.CommitAsync();}
    public async Task SaveRequestAdvancedAsync(LeaveRequestForm m,string? fileName,string? contentType,byte[]? content,Guid actor)
    {
        if(m.EndDate<m.StartDate)throw new InvalidOperationException("End date cannot be before start date.");
        await using var c=await Open();await using var tx=await c.BeginTransactionAsync();string? storedPath=null;string? absolutePath=null;
        try{
            bool allowHalf,requiresAttachment;decimal? max;
            await using(var type=new NpgsqlCommand("SELECT allow_half_day,max_consecutive_days,requires_attachment FROM leave_mgmt.leave_type WHERE id=@id AND is_active=true",c,tx)){type.Parameters.AddWithValue("id",m.LeaveTypeId!.Value);await using var r=await type.ExecuteReaderAsync();if(!await r.ReadAsync())throw new InvalidOperationException("Leave type is inactive.");allowHalf=r.GetBoolean(0);max=D(r,1);requiresAttachment=r.GetBoolean(2);}
            if(requiresAttachment&&(content is null||content.Length==0))throw new InvalidOperationException("An attachment is required for this leave type.");
            if(m.IsHalfDay&&!allowHalf)throw new InvalidOperationException("This leave type does not allow half-day requests.");if(m.IsHalfDay&&m.StartDate!=m.EndDate)throw new InvalidOperationException("Half-day request must use the same start and end date.");
            await using(var overlap=new NpgsqlCommand("SELECT 1 FROM leave_mgmt.leave_request WHERE employee_id=@employee AND status IN ('pending','approved') AND daterange(start_date,end_date,'[]') && daterange(@from,@to,'[]') LIMIT 1",c,tx)){overlap.Parameters.AddWithValue("employee",m.EmployeeId!.Value);overlap.Parameters.AddWithValue("from",m.StartDate);overlap.Parameters.AddWithValue("to",m.EndDate);if(await overlap.ExecuteScalarAsync() is not null)throw new InvalidOperationException("The employee already has a pending or approved leave request in this date range.");}
            await using(var access=new NpgsqlCommand("SELECT EXISTS(SELECT 1 FROM leave_mgmt.employee_leave_policy ep JOIN leave_mgmt.leave_policy p ON p.id=ep.policy_id WHERE ep.employee_id=@employee AND p.leave_type_id=@type AND ep.effective_from<=@from AND (ep.effective_to IS NULL OR ep.effective_to>=@to) AND p.effective_from<=@from AND (p.effective_to IS NULL OR p.effective_to>=@to) AND (p.effective_to IS NULL OR p.effective_to>current_date))",c,tx)){access.Parameters.AddWithValue("employee",m.EmployeeId!.Value);access.Parameters.AddWithValue("type",m.LeaveTypeId.Value);access.Parameters.AddWithValue("from",m.StartDate);access.Parameters.AddWithValue("to",m.EndDate);if(!(bool)(await access.ExecuteScalarAsync())!)throw new InvalidOperationException("This employee has no active policy for the selected leave type.");}
            short[] weeklyOff=[];Guid? calendar=null;await using(var schedule=new NpgsqlCommand("SELECT p.weekly_off_days,s.holiday_calendar_id FROM attendance.employee_schedule s JOIN attendance.attendance_policy p ON p.id=s.policy_id WHERE s.employee_id=@employee AND s.effective_from<=@date AND (s.effective_to IS NULL OR s.effective_to>=@date) ORDER BY s.effective_from DESC LIMIT 1",c,tx)){schedule.Parameters.AddWithValue("employee",m.EmployeeId.Value);schedule.Parameters.AddWithValue("date",m.StartDate);await using var r=await schedule.ExecuteReaderAsync();if(await r.ReadAsync()){weeklyOff=r.GetFieldValue<short[]>(0);calendar=r.IsDBNull(1)?null:r.GetGuid(1);}}
            var workDates=new List<DateOnly>();for(var d=m.StartDate;d<=m.EndDate;d=d.AddDays(1)){var iso=(short)(((int)d.DayOfWeek+6)%7+1);if(weeklyOff.Contains(iso))continue;if(calendar is not null){await using var holiday=new NpgsqlCommand("SELECT 1 FROM attendance.holiday WHERE calendar_id=@calendar AND holiday_date=@date",c,tx);holiday.Parameters.AddWithValue("calendar",calendar.Value);holiday.Parameters.AddWithValue("date",d);if(await holiday.ExecuteScalarAsync() is not null)continue;}workDates.Add(d);}
            if(workDates.Count==0)throw new InvalidOperationException("Selected range contains no working days.");var days=m.IsHalfDay?0.5m:workDates.Count;if(max is not null&&days>max)throw new InvalidOperationException($"Maximum consecutive leave is {max:0.##} days.");
            await using var branch=new NpgsqlCommand("SELECT branch_id FROM hr.employee_assignment WHERE employee_id=@employee AND effective_from<=@date AND(effective_to IS NULL OR effective_to>=@date) ORDER BY effective_from DESC LIMIT 1",c,tx);branch.Parameters.AddWithValue("employee",m.EmployeeId.Value);branch.Parameters.AddWithValue("date",m.StartDate);var branchId=await branch.ExecuteScalarAsync() as Guid? ?? throw new InvalidOperationException("Employee has no active assignment.");
            var id=Guid.NewGuid();if(content is not null&&content.Length>0){if(content.Length>10*1024*1024)throw new InvalidOperationException("Attachment cannot exceed 10 MB.");var safe=string.Concat(Path.GetFileName(fileName??"attachment").Select(ch=>char.IsLetterOrDigit(ch)||ch is '.' or '-' or '_'?ch:'_'));var relative=Path.Combine("uploads","leave",m.EmployeeId.Value.ToString("N"),$"{id:N}-{safe}").Replace('\\','/');absolutePath=Path.Combine(environment.WebRootPath,relative.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(absolutePath)!);await File.WriteAllBytesAsync(absolutePath,content);storedPath="/"+relative;}
            await using(var q=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_request(id,employee_id,branch_id,leave_type_id,start_date,end_date,requested_days,reason,attachment_object_key,status,requested_at,created_by,updated_by) VALUES(@id,@employee,@branch,@type,@from,@to,@days,@reason,@attachment,'pending',now(),@actor,@actor)",c,tx)){q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("employee",m.EmployeeId.Value);q.Parameters.AddWithValue("branch",branchId);q.Parameters.AddWithValue("type",m.LeaveTypeId.Value);q.Parameters.AddWithValue("from",m.StartDate);q.Parameters.AddWithValue("to",m.EndDate);q.Parameters.AddWithValue("days",days);q.Parameters.AddWithValue("reason",m.Reason.Trim());P(q,"attachment",storedPath);q.Parameters.AddWithValue("actor",actor);await q.ExecuteNonQueryAsync();}
            foreach(var date in workDates){await using var d=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_request_day(leave_request_id,leave_date,day_fraction,created_by,updated_by) VALUES(@id,@date,@fraction,@actor,@actor)",c,tx);d.Parameters.AddWithValue("id",id);d.Parameters.AddWithValue("date",date);d.Parameters.AddWithValue("fraction",m.IsHalfDay?0.5m:1m);d.Parameters.AddWithValue("actor",actor);await d.ExecuteNonQueryAsync();}await tx.CommitAsync();
        }catch{await tx.RollbackAsync();if(absolutePath is not null&&File.Exists(absolutePath))File.Delete(absolutePath);throw;}
    }
    public async Task CancelRequestAsync(LeaveRequestItem x,string? notes,Guid actor){await using var c=await Open();await using var tx=await c.BeginTransactionAsync();if(x.Status=="approved"){await using var reverse=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_ledger(employee_id,leave_type_id,transaction_date,quantity,entry_type,leave_request_id,reference,created_by,updated_by) VALUES(@employee,@type,current_date,@quantity,'adjustment',@request,'Approved leave cancellation',@actor,@actor)",c,tx);reverse.Parameters.AddWithValue("employee",x.EmployeeId);reverse.Parameters.AddWithValue("type",x.LeaveTypeId);reverse.Parameters.AddWithValue("quantity",x.RequestedDays);reverse.Parameters.AddWithValue("request",x.Id);reverse.Parameters.AddWithValue("actor",actor);await reverse.ExecuteNonQueryAsync();await using var attendance=new NpgsqlCommand("UPDATE attendance.attendance_day SET status='absent',notes='Leave cancelled; recalculate attendance',updated_at=now(),updated_by=@actor WHERE employee_id=@employee AND work_date BETWEEN @from AND @to AND status='leave'",c,tx);attendance.Parameters.AddWithValue("actor",actor);attendance.Parameters.AddWithValue("employee",x.EmployeeId);attendance.Parameters.AddWithValue("from",x.StartDate);attendance.Parameters.AddWithValue("to",x.EndDate);await attendance.ExecuteNonQueryAsync();}await using var q=new NpgsqlCommand("UPDATE leave_mgmt.leave_request SET status='cancelled',decision_notes=@notes,updated_at=now(),updated_by=@actor WHERE id=@id AND status IN ('pending','approved')",c,tx);q.Parameters.AddWithValue("id",x.Id);P(q,"notes",notes);q.Parameters.AddWithValue("actor",actor);if(await q.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("Only pending or approved requests can be cancelled.");await tx.CommitAsync();}
    public async Task DecideAsync(LeaveRequestItem x,string status,string? notes,Guid actor){if(status is not("approved" or "rejected"))throw new InvalidOperationException("Invalid decision.");await using var c=await Open();await using var tx=await c.BeginTransactionAsync();if(status=="approved"){await using var policy=new NpgsqlCommand("SELECT COALESCE(b.balance,0),p.allow_negative_balance FROM leave_mgmt.leave_request r LEFT JOIN reporting.v_leave_balance b ON b.employee_id=r.employee_id AND b.leave_type_id=r.leave_type_id LEFT JOIN LATERAL(SELECT allow_negative_balance FROM leave_mgmt.employee_leave_policy ep JOIN leave_mgmt.leave_policy lp ON lp.id=ep.policy_id WHERE ep.employee_id=r.employee_id AND lp.leave_type_id=r.leave_type_id AND ep.effective_from<=r.start_date AND(ep.effective_to IS NULL OR ep.effective_to>=r.end_date) ORDER BY ep.effective_from DESC LIMIT 1)p ON true WHERE r.id=@id",c,tx);policy.Parameters.AddWithValue("id",x.Id);await using var r=await policy.ExecuteReaderAsync();if(!await r.ReadAsync())throw new InvalidOperationException("Request not found.");var balance=r.GetDecimal(0);var negative=!r.IsDBNull(1)&&r.GetBoolean(1);if(!negative&&balance<x.RequestedDays)throw new InvalidOperationException($"Insufficient leave balance. Available: {balance:0.##} days.");}
        if(status=="approved"&&!x.PolicyActive)throw new InvalidOperationException("This leave policy is inactive. Enable the policy before approving this request.");await using(var q=new NpgsqlCommand("UPDATE leave_mgmt.leave_request SET status=@status,decided_by=@actor,decided_at=now(),decision_notes=@notes,updated_at=now(),updated_by=@actor WHERE id=@id AND status='pending'",c,tx)){q.Parameters.AddWithValue("id",x.Id);q.Parameters.AddWithValue("status",status);q.Parameters.AddWithValue("actor",actor);P(q,"notes",notes);if(await q.ExecuteNonQueryAsync()==0)throw new InvalidOperationException("This request has already been decided.");}
        if(status=="approved"){await using var l=new NpgsqlCommand("INSERT INTO leave_mgmt.leave_ledger(employee_id,leave_type_id,transaction_date,quantity,entry_type,leave_request_id,reference,created_by,updated_by) VALUES(@employee,@type,current_date,@quantity,'taken',@request,'Approved leave',@actor,@actor)",c,tx);l.Parameters.AddWithValue("employee",x.EmployeeId);l.Parameters.AddWithValue("type",x.LeaveTypeId);l.Parameters.AddWithValue("quantity",-x.RequestedDays);l.Parameters.AddWithValue("request",x.Id);l.Parameters.AddWithValue("actor",actor);await l.ExecuteNonQueryAsync();await using var attendance=new NpgsqlCommand("UPDATE attendance.attendance_day SET status='leave',updated_at=now(),updated_by=@actor WHERE employee_id=@employee AND work_date BETWEEN @from AND @to AND entry_source='system'",c,tx);attendance.Parameters.AddWithValue("actor",actor);attendance.Parameters.AddWithValue("employee",x.EmployeeId);attendance.Parameters.AddWithValue("from",x.StartDate);attendance.Parameters.AddWithValue("to",x.EndDate);await attendance.ExecuteNonQueryAsync();}await tx.CommitAsync();}

    private static async Task<NpgsqlConnection> Open(){var c=new NpgsqlConnection(StaticConnection.conn);await c.OpenAsync();return c;}private static string? S(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static decimal? D(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetDecimal(i);private static DateOnly? ND(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetFieldValue<DateOnly>(i);private static DateTimeOffset? DTO(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetFieldValue<DateTimeOffset>(i);private static void P(NpgsqlCommand q,string n,object? value)=>q.Parameters.AddWithValue(n,value??DBNull.Value);
